def find_path(graph, start, goal):
    queue = []
    heappush(queue, (0, start))
    cost_to_reach = {start: 0}
    parent = {start: None}
    while queue:
        current_cost, current_node = heappop(queue)
        if current_node == goal:
            path = []
            while current_node:
                path.append(current_node)
                current_node = parent[current_node]
            return path[::-1]
        for neighbor in graph[current_node]:
            tentative_cost = cost_to_reach[current_node] + 1
            if tentative_cost < cost_to_reach.get(neighbor, float('inf')):
                cost_to_reach[neighbor] = tentative_cost
                parent[neighbor] = current_node
                heappush(queue, (tentative_cost, neighbor))
    return None
