def backtrack_search(graph, current, goal, visited, path):
    if current in visited:
        return False
    visited.add(current)
    if current == goal:
        path.append(current)
        return True
    for neighbor in graph[current]:
        if backtrack_search(graph, neighbor, goal, visited, path):
            path.append(current)
            return True
    path.pop()
    return False
