        def __init__(self, state, parent=None, cost=0, h=0):
            self.state = state
            self.parent = parent
            self.cost = cost
            self.h = h

        def __lt__(self, other):
            return self.cost + self.h < other.cost + other.h
    open_set = []
    heapq.heappush(open_set, Node(start, cost=0, h=heuristic(start, goal)))
    closed_set = set()
    while open_set:
        current_node = heapq.heappop(open_set)
        if current_node.state == goal:
            path = []
            while current_node:
                path.append(current_node.state)
                current_node = current_node.parent
            return path[::-1]
        closed_set.add(current_node.state)
        for neighbor in graph.get(current_node.state, []):
            if neighbor in closed_set:
                continue
            tentative_cost = current_node.cost + 1
            if neighbor not in [node.state for node in open_set]:
                heapq.heappush(open_set, Node(neighbor, parent=current_node, cost=tentative_cost, h=heuristic(neighbor, goal)))
            elif tentative_cost >= open_set[open_set.index(Node(neighbor))].cost:
                continue
            open_set[open_set.index(Node(neighbor))] = Node(neighbor, parent=current_node, cost=tentative_cost, h=heuristic(neighbor, goal))
    return None
