from heapq import heappop, heappush

def find_path(graph, start, goal):
    priority_queue = [(0, start)]
    path = {start: [(start, 0)]}
    while priority_queue:
        current_cost, current_node = heappop(priority_queue)
        if current_node == goal:
            return path[current_node]
        for neighbor, cost in graph.get(current_node, []):
            total_cost = current_cost + cost
            if neighbor not in path or total_cost < path[neighbor][-1][1]:
                path[neighbor] = [(current_node, total_cost)] + path.get(neighbor, [])
                heappush(priority_queue, (total_cost, neighbor))
    return None
