    frontier = {start}
    explored = set()
    path = {start: None}
    while frontier:
        current = min(frontier, key=lambda node: (len(graph[node]), node))
        if current == goal:
            path_list = []
            while current is not None:
                path_list.append(current)
                current = path.get(current)
            return path_list[::-1]
        frontier.remove(current)
